#include <iostream>
using namespace std;

int fibonacciRecursive(int n) {
    if (n <= 1) return n;
    return fibonacciRecursive(n - 1) + fibonacciRecursive(n - 2);
}

int fibonacciIterative(int n) {
    if (n <= 1) return n;

    int a = 0, b = 1;
    for (int i = 2; i <= n; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}

int main() {
    cout << "斐波那契数列前10项:" << endl;
    for (int i = 0; i < 10; i++) {
        cout << fibonacciIterative(i) << " ";
    }
    cout << endl;

    cout << "
第10项的值: " << fibonacciRecursive(10) << endl;

    return 0;
}
